package io.baozhu.atlas.api; import io.baozhu.atlas.security.SqlSafetyGuard; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/sql") public class SqlController {private final SqlSafetyGuard guard;public SqlController(SqlSafetyGuard g){guard=g;} @PostMapping("/review") public SqlReviewResponse review(@Valid @RequestBody SqlReviewRequest r){return guard.review(r.sql(),r.allowedTables());}}
